// Singleton named configuration as ValueMap
ValueMap props = resource.adaptTo(ConfigurationBuilder.class)
    .name("simple-config").asValueMap();
String param1 = props.get("stringParam", String.class);
int param2 = props.get("intParam", 5);

// Collection of configurations as ValueMaps
Collection<ValueMap> propsList = resource
    .adaptTo(ConfigurationBuilder.class)
    .name("simple-config").asValueMapCollection();

code-block-2.code:
@Configuration
public @interface MatrixConfig {
    String stringParam();
    int intParam() default 5;
    boolean boolParam();
}

// Access typed singleton configuration
MatrixConfig config = resource.adaptTo(ConfigurationBuilder.class)
    .as(MatrixConfig.class);
String param1 = config.stringParam();
int param2 = config.intParam();

// Configuration name is derived from annotation class name

