import static org.apache.sling.testing.mock.caconfig.ContextPlugins.CACONFIG;

public class MatrixConfigTest {

    @Rule
    public SlingContext context = new SlingContextBuilder()
        .plugin(CACONFIG)
        .build();

    @Before
    public void setUp() {
        // register configuration annotation class
        MockContextAwareConfig.registerAnnotationClasses(
            context, MatrixConfig.class);

        // write config values required for tests
        MockContextAwareConfig.writeConfiguration(context,
            "/content/region1", MatrixConfig.class,
            "stringParam", "value1",
            "intParam", 123);
    }
}
